examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
    ScrollView {
        MonarchAiMentionContext(
            MonarchMentionQuery.find(in: {{query}}),
            items: [
            MonarchAiMentionItem(id: {{directory.0.id}}, kind: .{{directory.0.kind|raw}}, label: {{directory.0.label}}, description: {{directory.0.description}}, tokens: {{directory.0.tokens}}),
            MonarchAiMentionItem(id: {{directory.1.id}}, kind: .{{directory.1.kind|raw}}, label: {{directory.1.label}}, description: {{directory.1.description}}, tokens: {{directory.1.tokens}}),
            MonarchAiMentionItem(id: {{directory.2.id}}, kind: .{{directory.2.kind|raw}}, label: {{directory.2.label}}, description: {{directory.2.description}}, tokens: {{directory.2.tokens}}),
            MonarchAiMentionItem(id: {{directory.3.id}}, kind: .{{directory.3.kind|raw}}, label: {{directory.3.label}}, description: {{directory.3.description}}, tokens: {{directory.3.tokens}}),
            MonarchAiMentionItem(id: {{directory.4.id}}, kind: .{{directory.4.kind|raw}}, label: {{directory.4.label}}, description: {{directory.4.description}}, tokens: {{directory.4.tokens}}),
            MonarchAiMentionItem(id: {{directory.5.id}}, kind: .{{directory.5.kind|raw}}, label: {{directory.5.label}}, description: {{directory.5.description}}, tokens: {{directory.5.tokens}}),
            MonarchAiMentionItem(id: {{directory.6.id}}, kind: .{{directory.6.kind|raw}}, label: {{directory.6.label}}, description: {{directory.6.description}}, isDisabled: {{directory.6.disabled}}),
            ]
        ) { item in
            context.append(item.contextItem)
        }
    }
    .frame(maxHeight: 560)
    MonarchAiPromptInput("Message the assistant", text: $draft, toolbar: { EmptyView() }, onSubmit: { _ in })
    MonarchAiContextChips(context) { id in
        context.removeAll { $0.id == id }
    }
}

examples.setupTemplate:
@State private var context = [
    MonarchAiContextItem(id: {{context.id}}, kind: .{{context.kind|raw}}, label: {{context.label}}, tokens: {{context.tokens}}, isRemovable: {{context.removable}}),
]
@State private var draft = {{query}}

